def uid(key):return str(uuid5(NAMESPACE_URL,'madar/eduhope/'+key))
def choice(key,prompt,labels,correct=0):
 options=[{'id':uid(key+':'+str(i)),'label':label} for i,label in enumerate(labels)]
 return {'type':'multiple_choice','prompt':prompt,'points':1,'config':{'options':options,'correct_option_id':options[correct]['id']}}

def main():
 teaching=json.loads((ROOT/'teaching.json').read_text())['authored_demonstration_lessons'];banks=[];reviews=[]
 for band in ['A1','A2','B1','B2','C1']:
  scenes=[lesson for lesson in teaching if lesson['cefr']==band];questions=[]
  for index,(first,second,answer,distractors) in enumerate(GRAMMAR[band]):
   for variant,prompt in enumerate([first,second]):questions.append(choice(f'{band}:grammar:{index}:{variant}','Choose the natural completion: '+prompt,[answer,*distractors]))
  vocabulary=[item for scene in scenes for item in scene['vocabulary']]
  for index,item in enumerate(vocabulary):
   other=[v for v in vocabulary if v['word']!=item['word']][:2]
   questions.append(choice(f'{band}:definition:{index}','Which word means: '+item['meaning'],[item['word'],*[v['word'] for v in other]]))
   questions.append(choice(f'{band}:meaning:{index}',f"In the topic’s context, what does “{item['word']}” mean?",[item['meaning'],*[v['meaning'] for v in other]]))
  for scene_index,scene in enumerate(scenes):
   for index,q in enumerate(scene['understanding']):questions.append(choice(f'{band}:reading:{scene_index}:{index}','Read the conversation.\n'+scene['dialogue']+'\n\n'+q['prompt'],q['choices']))
  for index,(claim,correct) in enumerate(FACTS[band]):
   scene=scenes[0 if index<3 else 1]
   questions.append({'type':'true_false','prompt':'Read the conversation.\n'+scene['dialogue']+'\n\nStatement: '+claim,'points':1,'config':{'correct_answer':correct}})
  assert len(questions)==58 and len({q['prompt'] for q in questions})==58
  for index,scene in enumerate(scenes):questions.append({'type':'written','prompt':scene['goal']+' Write an original response about your own university or everyday-life situation. Do not copy the dialogue.','points':5,'config':{'rubric':f'{band}: relevant response, clear meaning, appropriate expressions, coherent organization and language control suitable for this band. Human review required.','max_characters':3000}})
  for index,prompt in enumerate([scenes[0]['goal'],scenes[1]['goal'],'Explain a possible alternative to the speakers’ plan and give your reason.','Describe a comparable situation from your own experience.','Summarize what each speaker needs and propose a practical next step.']):questions.append({'type':'speaking','prompt':prompt+' Use your own words.','points':5,'config':{'rubric':f'{band}: assess relevance, intelligibility, appropriate language and fluency at this band; for B2/C1 include nuance and supported reasoning. Do not grade accent identity. Human review only.','max_duration_seconds':120,'max_size_bytes':10485760}})
  # Drawing62 of65 guarantees at least2 of5 speaking and at least57 objective/
  # written questions, while changing which questions appear on retakes.
  banks.append({'key':'exam.'+band,'cefr':band,'section_number':scenes[-1]['level'],'status':'draft','title':band+' provisional CEFR final — educator review required','passing_score':70,'max_attempts':5,'pool_size':62,'shuffle_questions':True,'shuffle_options':True,'questions':questions,'official_publication_approved':False})
 for scene in teaching:
  qs=[choice('review:'+scene['key']+':'+str(i),q['prompt'],q['choices']) for i,q in enumerate(scene['understanding'])]
  qs.append({'type':'written','prompt':scene['goal'],'points':5,'config':{'rubric':'A relevant, original response using the topic’s language. Human review required.','max_characters':1500}})
  reviews.append({'key':'review.level-'+str(scene['level']),'section_number':scene['level'],'title':'Level '+str(scene['level'])+' review — provisional','status':'draft','passing_score':70,'max_attempts':5,'questions':qs})
 (ROOT/'assessments.json').write_text(json.dumps({'version':1,'provisional':True,'educator_review_required':True,'level_reviews':reviews,'cefr_finals':banks},ensure_ascii=False,indent=2)+'\n')
 print('Authored10 draft Level reviews and5 distinct65-question CEFR banks; each draw62 guarantees2–5 speaking questions. No DB writes.')
if __name__=='__main__':main()
